/**
 * Contorno do Brasil por unidade da federação — malha OFICIAL do IBGE.
 *
 * Gerado a partir de
 * `servicodados.ibge.gov.br/api/v3/malhas/paises/BR` (qualidade intermediária,
 * intrarregião UF), projetado em Mercator e simplificado por Douglas-Peucker
 * com tolerância de 0,28 unidade do viewBox: 5.128 pontos no total.
 *
 * O que havia antes eram polígonos desenhados à mão, de 10 a 20 pontos por
 * estado, só com segmentos retos — uma silhueta aproximada. Servia para dizer
 * "isto é o Brasil", mas os estados não tinham a forma deles, e num painel que
 * usa o mapa para LER concentração de licitação isso é um erro de leitura, não
 * de estética: a pessoa procura o estado dela e não reconhece.
 *
 * Ilhas oceânicas ficaram de fora (Fernando de Noronha, Trindade, Martim Vaz,
 * Atol das Rocas). Não é descuido: elas ficam a centenas de quilômetros da
 * costa e esticariam a caixa do desenho, encolhendo o continente para caber o
 * oceano. O corte é por área — anel com menos de 0,4% do maior anel do próprio
 * estado sai.
 *
 * A cor de cada estado NÃO vive aqui: ela sai da escala `--map-1..6` de
 * `index.css`, aplicada em runtime conforme o volume de licitações.
 *
 * Para regerar: `scripts/gerar-mapa-brasil.py`.
 */

export interface ContornoUF {
  uf: string;
  nome: string;
  d: string;
  /** Centro do maior anel — âncora do rótulo com a sigla. */
  cx: number;
  cy: number;
  /** Área do maior anel em unidades do viewBox. Estado pequeno não recebe
   *  rótulo: a sigla ficaria maior que o próprio estado. */
  area: number;
}

